import React, { useEffect, useMemo, useState } from "react";

function Loading() {
  return (
    <div className="min-h-screen flex items-center justify-center bg-blue-50 text-gray-800 p-6">
      <div className="bg-white rounded-2xl shadow p-6 w-full max-w-md text-center">
        <h1 className="text-2xl font-semibold mb-2">Ładowanie pytań…</h1>
        <p className="text-sm text-gray-500">
          Proszę czekać, trwa wczytywanie pliku JSON.
        </p>
      </div>
    </div>
  );
}

function ErrorBox({ message, onRetry }) {
  return (
    <div className="min-h-screen flex items-center justify-center bg-red-50 text-gray-800 p-6">
      <div className="bg-white rounded-2xl shadow p-6 w-full max-w-md">
        <h1 className="text-2xl font-bold text-red-600 mb-3">Błąd</h1>
        <p className="mb-4 text-sm text-gray-700">{message}</p>
        {onRetry && (
          <button
            onClick={onRetry}
            className="bg-red-600 text-white px-4 py-2 rounded-lg shadow hover:bg-red-700"
          >
            Spróbuj ponownie
          </button>
        )}
      </div>
    </div>
  );
}

function StartScreen({ onStart, defaultName = "" }) {
  const [name, setName] = useState(defaultName);
  const [consent, setConsent] = useState(true);

  const handleStart = () => {
    // Zapamiętaj imię lokalnie (opcjonalne)
    try {
      window.localStorage.setItem("quiz_student_name", name || "");
    } catch {}
    onStart(name || "");
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-blue-50 text-gray-800 p-6">
      <div className="bg-white shadow-lg rounded-2xl p-6 w-full max-w-md">
        <h1 className="text-3xl font-bold mb-2">Quiz - Nauka Python - 1</h1>
        <p className="text-sm text-gray-600 mb-6">
          20 pytań, odpowiedzi A–D. Powodzenia!
        </p>

        <label className="block text-sm font-medium mb-1">
          Imię i nazwisko (opcjonalnie)
        </label>
        <input
          value={name}
          onChange={(e) => setName(e.target.value)}
          placeholder="np. Jan Kowalski"
          className="w-full border rounded-lg p-2 mb-4 focus:outline-none focus:ring"
        />

        <label className="flex items-start gap-2 text-sm text-gray-600 mb-6">
          <input
            type="checkbox"
            checked={consent}
            onChange={(e) => setConsent(e.target.checked)}
          />
          <span>Rozpoczynając, potwierdzam gotowość do rozwiązania testu.</span>
        </label>

        <button
          onClick={handleStart}
          disabled={!consent}
          className="bg-blue-500 disabled:opacity-60 text-white px-4 py-2 rounded-lg shadow hover:bg-blue-600 w-full"
        >
          Rozpocznij quiz
        </button>
      </div>
    </div>
  );
}

export default function App() {
  const [questions, setQuestions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  const [started, setStarted] = useState(false);
  const [studentName, setStudentName] = useState("");

  const [current, setCurrent] = useState(0);
  const [score, setScore] = useState(0);
  const [finished, setFinished] = useState(false);

  // Wczytanie pytań z public/questions.json
  const fetchQuestions = async () => {
    try {
      setLoading(true);
      setError("");
      const res = await fetch("/questions.json", { cache: "no-store" });
      if (!res.ok)
        throw new Error(
          `Nie udało się pobrać questions.json (HTTP ${res.status}).`
        );
      const data = await res.json();

      // Prosta walidacja struktury
      if (!Array.isArray(data))
        throw new Error("Plik JSON musi zawierać tablicę pytań.");
      data.forEach((q, i) => {
        if (typeof q.question !== "string")
          throw new Error(`Pytanie #${i + 1}: brak pola 'question' (string).`);
        if (!Array.isArray(q.options) || q.options.length !== 4)
          throw new Error(
            `Pytanie #${i + 1}: 'options' musi mieć 4 odpowiedzi.`
          );
        if (
          typeof q.correctAnswer !== "number" ||
          q.correctAnswer < 0 ||
          q.correctAnswer > 3
        )
          throw new Error(
            `Pytanie #${i + 1}: 'correctAnswer' musi być liczbą 0–3.`
          );
      });

      setQuestions(data);
      setCurrent(0);
      setScore(0);
      setFinished(false);
    } catch (e) {
      setError(e.message || "Nieznany błąd podczas wczytywania pytań.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchQuestions();
    try {
      const saved = window.localStorage.getItem("quiz_student_name");
      if (saved) setStudentName(saved);
    } catch {}
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const progress = useMemo(() => {
    if (!questions.length) return 0;
    return Math.round((current / questions.length) * 100);
  }, [current, questions.length]);

  const handleAnswer = (index) => {
    if (!questions.length) return;
    if (index === questions[current].correctAnswer) setScore((s) => s + 1);

    const next = current + 1;
    if (next < questions.length) setCurrent(next);
    else setFinished(true);
  };

  const restart = () => {
    setScore(0);
    setCurrent(0);
    setFinished(false);
    setStarted(false);
  };

  if (loading) return <Loading />;
  if (error) return <ErrorBox message={error} onRetry={fetchQuestions} />;
  if (!questions.length)
    return (
      <ErrorBox message={"Brak pytań w pliku JSON."} onRetry={fetchQuestions} />
    );

  if (!started) {
    return (
      <StartScreen
        onStart={(name) => {
          setStudentName(name);
          setStarted(true);
        }}
        defaultName={studentName}
      />
    );
  }

  if (finished) {
    const percent = Math.round((score / questions.length) * 100);
    return (
      <div className="min-h-screen flex items-center justify-center bg-blue-50 text-gray-800 p-6">
        <div className="bg-white shadow-lg rounded-2xl p-6 w-full max-w-md text-center">
          <h1 className="text-3xl font-bold mb-1">Twój wynik</h1>
          {studentName && (
            <p className="text-sm text-gray-500 mb-1">
              Rozwiązujący: <strong>{studentName}</strong>
            </p>
          )}
          <p className="text-xl mb-6">
            {score} / {questions.length} poprawnych ({percent}%)
          </p>
          <div className="flex gap-3 justify-center">
            <button
              onClick={restart}
              className="bg-blue-500 text-white px-4 py-2 rounded-lg shadow hover:bg-blue-600"
            >
              Zagraj ponownie
            </button>
            <button
              onClick={fetchQuestions}
              className="bg-gray-100 px-4 py-2 rounded-lg shadow hover:bg-gray-200"
            >
              Wczytaj pytania ponownie
            </button>
          </div>
        </div>
      </div>
    );
  }

  const q = questions[current];

  return (
    <div className="min-h-screen flex items-center justify-center bg-blue-50 text-gray-800 p-6">
      <div className="bg-white shadow-lg rounded-2xl p-6 w-full max-w-md">
        <div className="flex items-center justify-between mb-4">
          <div>
            <h1 className="text-xl font-semibold">
              Pytanie {current + 1} z {questions.length}
            </h1>
            {studentName && (
              <p className="text-xs text-gray-500">
                Rozwiązujący: {studentName}
              </p>
            )}
          </div>
          <span className="text-sm text-gray-500">{progress}%</span>
        </div>
        <div className="w-full h-2 bg-gray-200 rounded-full mb-4">
          <div
            className="h-2 bg-blue-500 rounded-full"
            style={{ width: `${progress}%` }}
          />
        </div>
        <p className="text-lg mb-4">{q.question}</p>
        <div className="grid gap-3">
          {q.options.map((opt, i) => (
            <button
              key={i}
              onClick={() => handleAnswer(i)}
              className="bg-blue-100 hover:bg-blue-200 text-left p-3 rounded-lg transition"
            >
              {String.fromCharCode(65 + i)}. {opt}
            </button>
          ))}
        </div>
        <div className="flex items-center justify-between mt-6 text-sm text-gray-500">
          <span>Wynik: {score}</span>
          <button onClick={restart} className="underline hover:text-gray-700">
            Zakończ
          </button>
        </div>
      </div>
    </div>
  );
}
